CREATE DATABASE IF NOT EXISTS anggaran_dprd CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE anggaran_dprd;

CREATE TABLE IF NOT EXISTS ci_sessions (id VARCHAR(128) NOT NULL PRIMARY KEY, ip_address VARCHAR(45) NOT NULL, timestamp INT UNSIGNED NOT NULL DEFAULT 0, data BLOB NOT NULL, KEY ci_sessions_timestamp (timestamp));
CREATE TABLE IF NOT EXISTS tahun_anggaran (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tahun SMALLINT UNSIGNED NOT NULL UNIQUE, is_locked TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS penerima (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nama VARCHAR(150) NOT NULL, tipe VARCHAR(30) NOT NULL, jabatan VARCHAR(80) NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_penerima_tipe (tipe));
CREATE TABLE IF NOT EXISTS jenis_biaya (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, kode VARCHAR(30) NOT NULL UNIQUE, nama VARCHAR(120) NOT NULL, satuan VARCHAR(30) NULL, is_active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sumber_dana (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, kode VARCHAR(30) NOT NULL UNIQUE, nama VARCHAR(150) NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(60) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, nama VARCHAR(150) NOT NULL, role VARCHAR(20) NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, login_failures TINYINT UNSIGNED NOT NULL DEFAULT 0, locked_until DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS roles (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, kode VARCHAR(30) NOT NULL UNIQUE, nama VARCHAR(100) NOT NULL, keterangan VARCHAR(255) NULL, is_system TINYINT(1) NOT NULL DEFAULT 0, aktif TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS permissions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, kode VARCHAR(60) NOT NULL UNIQUE, modul VARCHAR(30) NOT NULL, nama VARCHAR(120) NOT NULL);
CREATE TABLE IF NOT EXISTS role_permissions (role_id INT UNSIGNED NOT NULL, permission_id INT UNSIGNED NOT NULL, PRIMARY KEY(role_id,permission_id), CONSTRAINT fk_schema_rp_role FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE, CONSTRAINT fk_schema_rp_perm FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS anggaran (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tahun_anggaran_id INT UNSIGNED NOT NULL, penerima_id INT UNSIGNED NOT NULL, sumber_dana_id INT UNSIGNED NULL, pagu DECIMAL(18,2) NOT NULL DEFAULT 0, UNIQUE KEY uq_anggaran (tahun_anggaran_id,penerima_id), CONSTRAINT fk_anggaran_tahun FOREIGN KEY (tahun_anggaran_id) REFERENCES tahun_anggaran(id), CONSTRAINT fk_anggaran_penerima FOREIGN KEY (penerima_id) REFERENCES penerima(id), CONSTRAINT fk_anggaran_sumber FOREIGN KEY (sumber_dana_id) REFERENCES sumber_dana(id));
CREATE TABLE IF NOT EXISTS anggaran_rincian (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, anggaran_id INT UNSIGNED NOT NULL, jenis_biaya_id INT UNSIGNED NOT NULL, pagu DECIMAL(18,2) NOT NULL DEFAULT 0, UNIQUE KEY uq_anggaran_rincian (anggaran_id,jenis_biaya_id));
CREATE TABLE IF NOT EXISTS kegiatan (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tahun_anggaran_id INT UNSIGNED NOT NULL, nama_kegiatan VARCHAR(200) NOT NULL, no_surat_tugas VARCHAR(100) NULL, tanggal_surat_tugas DATE NULL, tema VARCHAR(255) NULL, tanggal_input DATE NOT NULL, tanggal_mulai DATE NOT NULL, tanggal_selesai DATE NOT NULL, tempat VARCHAR(200) NULL, status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', total DECIMAL(18,2) NOT NULL DEFAULT 0, alasan_batal TEXT NULL, created_by INT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NULL DEFAULT NULL, INDEX idx_kegiatan_tanggal (tanggal_mulai), INDEX idx_kegiatan_status (status), CONSTRAINT fk_kegiatan_tahun FOREIGN KEY (tahun_anggaran_id) REFERENCES tahun_anggaran(id));
CREATE TABLE IF NOT EXISTS kegiatan_peserta (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, kegiatan_id INT UNSIGNED NOT NULL, penerima_id INT UNSIGNED NOT NULL, sumber_dana_id INT UNSIGNED NULL, UNIQUE KEY uq_kegiatan_peserta (kegiatan_id,penerima_id), CONSTRAINT fk_kp_kegiatan FOREIGN KEY (kegiatan_id) REFERENCES kegiatan(id) ON DELETE CASCADE, CONSTRAINT fk_kp_penerima FOREIGN KEY (penerima_id) REFERENCES penerima(id), CONSTRAINT fk_kp_sumber FOREIGN KEY (sumber_dana_id) REFERENCES sumber_dana(id));
CREATE TABLE IF NOT EXISTS kegiatan_biaya (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, kegiatan_peserta_id INT UNSIGNED NOT NULL, jenis_biaya_id INT UNSIGNED NOT NULL, volume DECIMAL(14,2) NOT NULL DEFAULT 0, tarif DECIMAL(18,2) NOT NULL DEFAULT 0, subtotal DECIMAL(18,2) AS (volume * tarif) STORED, CONSTRAINT fk_kb_peserta FOREIGN KEY (kegiatan_peserta_id) REFERENCES kegiatan_peserta(id) ON DELETE CASCADE, CONSTRAINT fk_kb_jenis FOREIGN KEY (jenis_biaya_id) REFERENCES jenis_biaya(id));
CREATE TABLE IF NOT EXISTS audit_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, entity VARCHAR(50) NOT NULL, entity_id INT UNSIGNED NOT NULL, action VARCHAR(30) NOT NULL, old_data JSON NULL, new_data JSON NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_audit_entity (entity,entity_id));
CREATE TABLE IF NOT EXISTS laporan_tersimpan (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, nama VARCHAR(150) NOT NULL, config JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);

CREATE OR REPLACE VIEW v_realisasi AS SELECT k.tahun_anggaran_id, kp.penerima_id, SUM(kb.volume*kb.tarif) realisasi FROM kegiatan k JOIN kegiatan_peserta kp ON kp.kegiatan_id=k.id JOIN kegiatan_biaya kb ON kb.kegiatan_peserta_id=kp.id WHERE k.status = 'AKTIF' GROUP BY k.tahun_anggaran_id,kp.penerima_id;
CREATE OR REPLACE VIEW v_sisa_anggaran AS SELECT a.tahun_anggaran_id,a.penerima_id,p.nama,p.tipe,p.jabatan,a.pagu,COALESCE(r.realisasi,0) realisasi,(a.pagu-COALESCE(r.realisasi,0)) sisa FROM anggaran a JOIN penerima p ON p.id=a.penerima_id LEFT JOIN v_realisasi r ON r.tahun_anggaran_id=a.tahun_anggaran_id AND r.penerima_id=a.penerima_id;
CREATE OR REPLACE VIEW v_detail_biaya AS SELECT k.id kegiatan_id,k.tahun_anggaran_id,k.nama_kegiatan,k.no_surat_tugas,k.tanggal_surat_tugas,k.tema,k.tanggal_input,k.tanggal_mulai,k.tanggal_selesai,k.tempat,k.status,kp.penerima_id,p.nama penerima_nama,p.tipe,p.jabatan,kp.sumber_dana_id,sd.kode sumber_dana_kode,sd.nama sumber_dana_nama,j.id jenis_biaya_id,j.kode jenis_biaya_kode,j.nama jenis_biaya_nama,kb.volume,kb.tarif,(kb.volume*kb.tarif) subtotal FROM kegiatan k JOIN kegiatan_peserta kp ON kp.kegiatan_id=k.id JOIN penerima p ON p.id=kp.penerima_id LEFT JOIN sumber_dana sd ON sd.id=kp.sumber_dana_id JOIN kegiatan_biaya kb ON kb.kegiatan_peserta_id=kp.id JOIN jenis_biaya j ON j.id=kb.jenis_biaya_id;
